// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(this));
    }

    function _run(uint256 _am, uint256 _depAmt) internal {
        _depAmt = bound(_depAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        vm.assume(address(this).balance >= _depAmt);
        try c.CashOut(_am) {} catch { return; }
        bool reverted;
        try c.Deposit{value: _depAmt}() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted);
    }

    function testFuzz_run(uint256 _am, uint256 _depAmt) public {
        _run(_am, _depAmt);
    }

    receive() external payable {}
}
